    ck("小计 = ¥1,158（459+699）", pg.inner_text("#sub") == "¥1,158", pg.inner_text("#sub"))
    ck("满 399 免运费生效", pg.inner_text("#ship") == "免运费", pg.inner_text("#ship"))
